using Microsoft.Data.Sqlite;
namespace ClinixMX.Data;
public sealed class ClinixDb
{
    private readonly string _path;
    public ClinixDb(){var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ClinixMX");Directory.CreateDirectory(dir);_path=Path.Combine(dir,"clinix.db");Initialize();}
    private SqliteConnection Open()=>new($"Data Source={_path};Cache=Shared");
    private void Initialize(){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText=@"PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS Patients(Id INTEGER PRIMARY KEY AUTOINCREMENT,FullName TEXT NOT NULL,BirthDate TEXT,Sex TEXT,Phone TEXT,Email TEXT,Address TEXT,EmergencyContact TEXT,Allergies TEXT,MedicalHistory TEXT,Medications TEXT,BloodType TEXT,CreatedAt TEXT NOT NULL,UpdatedAt TEXT NOT NULL); CREATE TABLE IF NOT EXISTS Consultations(Id INTEGER PRIMARY KEY AUTOINCREMENT,PatientId INTEGER NOT NULL,Date TEXT NOT NULL,Reason TEXT,Notes TEXT,Diagnosis TEXT,Treatment TEXT,CreatedBy TEXT); CREATE TABLE IF NOT EXISTS AuditLog(Id INTEGER PRIMARY KEY AUTOINCREMENT,UserName TEXT NOT NULL,Action TEXT NOT NULL,Entity TEXT,EntityId INTEGER,CreatedAt TEXT NOT NULL);";cmd.ExecuteNonQuery();}
    public List<(long Id,string Name,string Phone)> SearchPatients(string q){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT Id,FullName,COALESCE(Phone,'') FROM Patients WHERE FullName LIKE $q OR Phone LIKE $q ORDER BY FullName LIMIT 200";cmd.Parameters.AddWithValue("$q","%"+q+"%");using var r=cmd.ExecuteReader();var list=new List<(long,string,string)>();while(r.Read())list.Add((r.GetInt64(0),r.GetString(1),r.GetString(2)));return list;}
    public long AddPatient(string name,string birth,string sex,string phone,string email,string address,string emergency,string allergies,string history,string meds,string blood){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO Patients(FullName,BirthDate,Sex,Phone,Email,Address,EmergencyContact,Allergies,MedicalHistory,Medications,BloodType,CreatedAt,UpdatedAt) VALUES($n,$b,$s,$p,$e,$a,$em,$al,$h,$m,$bt,$now,$now); SELECT last_insert_rowid();";cmd.Parameters.AddWithValue("$n",name);cmd.Parameters.AddWithValue("$b",birth);cmd.Parameters.AddWithValue("$s",sex);cmd.Parameters.AddWithValue("$p",phone);cmd.Parameters.AddWithValue("$e",email);cmd.Parameters.AddWithValue("$a",address);cmd.Parameters.AddWithValue("$em",emergency);cmd.Parameters.AddWithValue("$al",allergies);cmd.Parameters.AddWithValue("$h",history);cmd.Parameters.AddWithValue("$m",meds);cmd.Parameters.AddWithValue("$bt",blood);cmd.Parameters.AddWithValue("$now",DateTime.UtcNow.ToString("O"));var id=(long)cmd.ExecuteScalar()!;Audit("Sistema","Alta de paciente","Patients",id);return id;}
    public void AddConsultation(long patientId,string reason,string notes,string diagnosis,string treatment,string user){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO Consultations(PatientId,Date,Reason,Notes,Diagnosis,Treatment,CreatedBy) VALUES($p,$d,$r,$n,$di,$t,$u)";cmd.Parameters.AddWithValue("$p",patientId);cmd.Parameters.AddWithValue("$d",DateTime.Now.ToString("s"));cmd.Parameters.AddWithValue("$r",reason);cmd.Parameters.AddWithValue("$n",notes);cmd.Parameters.AddWithValue("$di",diagnosis);cmd.Parameters.AddWithValue("$t",treatment);cmd.Parameters.AddWithValue("$u",user);cmd.ExecuteNonQuery();Audit(user,"Nueva consulta","Consultations",patientId);}
    public void Audit(string user,string action,string? entity=null,long? id=null){using var c=Open();c.Open();using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO AuditLog(UserName,Action,Entity,EntityId,CreatedAt) VALUES($u,$a,$e,$i,$d)";cmd.Parameters.AddWithValue("$u",user);cmd.Parameters.AddWithValue("$a",action);cmd.Parameters.AddWithValue("$e",(object?)entity??DBNull.Value);cmd.Parameters.AddWithValue("$i",(object?)id??DBNull.Value);cmd.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));cmd.ExecuteNonQuery();}
    public string Backup(){var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"ClinixMX-Backups");Directory.CreateDirectory(dir);var target=Path.Combine(dir,$"clinix-{DateTime.Now:yyyyMMdd-HHmmss}.db");File.Copy(_path,target,true);Audit("Sistema","Backup creado");return target;}
}
